$db=TestSupport::db();TestSupport::seed($db);Schema::install($db);Kulturhus\Native\Cms\Schema::install($db);$access=new Access($db,'admin');$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/clone-runtime';mkdir($root,0700,true);$media=new Media($db,$access,$root.'/media');$checks=0;
