foreach([null,'[]',[$stamp+['url'=>'https://example.invalid']],array_fill(0,65,$stamp),[array_diff_key($stamp,['radius'=>true])],[array_replace($stamp,['source_x'=>'25'])],[array_replace($stamp,['source_x'=>NAN])],[array_replace($stamp,['source_x'=>INF])],[array_replace($stamp,['radius'=>0])],[array_replace($stamp,['radius'=>26])],[array_replace($stamp,['target_y'=>1])],[array_replace($stamp,['source_x'=>99])]]as $bad)denied(fn()=>PhotoClones::validate($bad),'malformed, external, oversized or out-of-photo stamp rejected');
