$identity=(new Identity($db,$access))->save(['name'=>'Own retouch originals','origin'=>'https://example.invalid','logo_id'=>'','address'=>''],0);$work=new Workspace($db,$access,'social');$item=$work->save(['title'=>'Own private clone composition','body'=>'Exact original content']);$images=new Images($db,$access,$root.'/media');
$document=['schema'=>1,'width'=>1080,'height'=>1350,'background'=>'#163f33','layers'=>[['id'=>'photo','type'=>'image','x'=>50,'y'=>100,'width'=>800,'height'=>400,'media_ref'=>$photo['id']]]];$old=CanvasDocument::validate($document,'post');
check(!array_key_exists('clone_stamps',$old['layers'][0]),'old approved artwork has no new empty clone metadata');$empty=$document;$empty['layers'][0]['clone_stamps']=[];check(CanvasDocument::validate($empty,'post')===$old,'empty clone list preserves canonical old artwork');
$cloned=$document;$cloned['layers'][0]['clone_stamps']=[$stamp];$normalized=CanvasDocument::validate($cloned,'post');$unchanged=$normalized;unset($unchanged['layers'][0]['clone_stamps']);check($unchanged===$old,'manual clone preserves every unrelated original photo and composition value');
$budget=$cloned;$budget['layers']=[];for($i=0;$i<4;$i++){$layer=$cloned['layers'][0];$layer['id']='photo-'.$i;$layer['clone_stamps']=array_fill(0,64,$stamp);$budget['layers'][]=$layer;}check(count(CanvasDocument::validate($budget,'post')['layers'])===4,'256 stamps accepted at exact whole-document boundary');$extra=$budget['layers'][0];$extra['id']='overflow';$extra['clone_stamps']=[$stamp];$budget['layers'][]=$extra;denied(fn()=>CanvasDocument::validate($budget,'post'),'whole-document clone processing budget enforced');
$bad=$cloned;$bad['layers'][0]=['id'=>'rect','type'=>'rect','x'=>50,'y'=>50,'width'=>500,'height'=>300,'color'=>'#ffffff','clone_stamps'=>[$stamp]];denied(fn()=>CanvasDocument::validate($bad,'post'),'manual clone cannot be silently applied to a non-photo layer');
$canvas=imagecreatetruecolor(1080,1350);imagefill($canvas,0,0,imagecolorallocate($canvas,22,63,51));imagepng($canvas,$root.'/canvas.png');unset($canvas);$first=$images->saveCanvas($item['id'],$item['version'],$identity['version'],0,$old,$root.'/canvas.png');$firstHash=hash_file('sha256',$images->file($first)['path']);$approved=$work->approve($item['id'],$item['version']);$jobs=(int)Db::run($db,'SELECT COUNT(*) FROM native_delivery_jobs')->fetchColumn();$second=$images->saveCanvas($item['id'],$approved['version'],$identity['version'],0,$cloned,$root.'/canvas.png');$history=$images->history($item['id']);$metadata=json_decode($history[0]['metadata_json'],true,32,JSON_THROW_ON_ERROR);
check(CanvasDocument::validate($metadata['document'],'post')===$normalized,'server preserves exact editable manual retouch document');check($work->get($item['id'])===$approved&&$approved['approved_image_ids']===[$first],'new retouch is private and does not replace an earlier exact approval');check($first!==$second&&hash_file('sha256',$images->file($first)['path'])===$firstHash,'retouch stores a new artwork without changing earlier approved bytes');
foreach(['original','large','medium','thumb']as $variant)check(hash_file('sha256',$media->variant($photo['id'],$variant)['path'])===$hashes[$variant],'source photo variant remains byte-identical: '.$variant);
denied(fn()=>$images->saveCanvas($item['id'],$approved['version']-1,$identity['version'],0,$cloned,$root.'/canvas.png'),'stale content cannot store retouched artwork');denied(fn()=>(new Images($db,new Access($db,'reader'),$root.'/media'))->saveCanvas($item['id'],$approved['version'],$identity['version'],0,$cloned,$root.'/canvas.png'),'read-only role cannot store retouch');denied(fn()=>(new Images($db,new Access($db,'outsider'),$root.'/media'))->file($second),'foreign club cannot read private retouch');check((int)Db::run($db,'SELECT COUNT(*) FROM native_delivery_jobs')->fetchColumn()===$jobs,'manual retouch creates no provider or delivery job');
